exec python3 -c 'import sys,json;from functools import reduce;s=sys.argv[1]if len(sys.argv)>1 else"111";assert set(s)<=set("1");N=len(s);C=lambda n,q:[q,n,"X"*min(n,N)+s[n:]+("_"if n==N else"")];R={"0|1":[0,"X",1],"0|_":[1,"_",0]};H=[{"step":n,"pre":C(n,0),"read":"1"if n<N else"_","write":"X"if n<N else"_","move":1 if n<N else 0,"post":C(n+1,0)if n<N else C(n,1)}for n in range(N+1)];assert all(R[str(x["pre"][0])+"|"+x["read"]]==[x["post"][0],x["write"],x["move"]]for x in H);assert all(H[n]["post"]==H[n+1]["pre"]for n in range(N));assert H[-1]["post"][0]==1;B=[json.dumps(x,sort_keys=True,separators=(",",":")).encode()for x in H];assert all(bytes.fromhex(b.hex())==b for b in B);G=lambda b:reduce(lambda a,v:a*257+v+1,b,1);print(json.dumps({"system":"TM-011","time_particle_model":"LOGICAL_CHRONON","temporal_state":"TEMPORALLY_CLOSED","completeness_scope":"FINITE_HALTING_TRACE","input":s,"chronons":H,"chronon_codes":[str(G(b))for b in B],"steps":len(H),"trace_contiguous":True,"trace_exact":True,"replayable":True,"conditional_entropy_bits":0,"float_used":False,"sha_used":False,"physical_time_particle_proven":False,"time_travel_proven":False},separators=(",",":")))' "$@"
